package com.cezar.dev.airquality.services;
import com.cezar.dev.airquality.clients.OpenMeteoClient; import com.cezar.dev.airquality.dtos.*; import com.cezar.dev.airquality.exceptions.*; import org.springframework.stereotype.Service;
@Service public class WeatherService { private final OpenMeteoClient client; public WeatherService(OpenMeteoClient client){this.client=client;}
 public WeatherResponse current(Double lat, Double lon) { if(lat==null||lon==null||!Double.isFinite(lat)||!Double.isFinite(lon)||lat < -90||lat >90||lon < -180||lon >180) throw new InvalidRequestException("INVALID_COORDINATES"); var f=client.weather(lat,lon); if(f.current()==null||f.timezone()==null) throw new UpstreamException(); var c=f.current(); return new WeatherResponse(f.latitude(),f.longitude(),f.timezone(),c.time(),c.temperature_2m(),c.apparent_temperature(),c.relative_humidity_2m(),c.precipitation(),c.wind_speed_10m(),c.wind_direction_10m(),cardinal(c.wind_direction_10m()),c.weather_code(),condition(c.weather_code()),c.is_day()==1); }
 public static String cardinal(int d) { String[] all={"N","NE","E","SE","S","SO","O","NO"}; return all[Math.floorMod((int)Math.round(d/45.0),8)]; }
 public static String condition(int code) { return switch(code) { case 0->"Céu limpo"; case 1->"Predominantemente limpo"; case 2->"Parcialmente nublado"; case 3->"Nublado"; case 45->"Nevoeiro"; case 48->"Nevoeiro com geada"; case 51->"Garoa fraca"; case 53->"Garoa moderada"; case 55->"Garoa intensa"; case 56->"Garoa congelante fraca"; case 57->"Garoa congelante intensa"; case 61->"Chuva fraca"; case 63->"Chuva moderada"; case 65->"Chuva forte"; case 66->"Chuva congelante fraca"; case 67->"Chuva congelante forte"; case 71->"Neve fraca"; case 73->"Neve moderada"; case 75->"Neve forte"; case 77->"Grãos de neve"; case 80->"Pancadas de chuva fracas"; case 81->"Pancadas de chuva moderadas"; case 82->"Pancadas de chuva violentas"; case 85->"Pancadas de neve fracas"; case 86->"Pancadas de neve fortes"; case 95->"Trovoada"; case 96->"Trovoada com granizo fraco"; case 99->"Trovoada com granizo forte"; default->"Condição desconhecida"; }; } }
